PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','coach','student')),code TEXT,cref TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive','review')),must_change_password INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at TEXT);
CREATE TABLE students(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE,coach_id INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',program_name TEXT NOT NULL DEFAULT 'Programa inicial',phase TEXT NOT NULL DEFAULT 'Fase 1',age INTEGER NOT NULL DEFAULT 0,height REAL NOT NULL DEFAULT 0,weight REAL NOT NULL DEFAULT 0,body_fat REAL NOT NULL DEFAULT 0,plan_name TEXT,avatar TEXT,notes TEXT,last_check_in TEXT,joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE coach_profiles(user_id INTEGER PRIMARY KEY,specialty TEXT,unit TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_reset_tokens(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,details TEXT,ip_hash TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments(id INTEGER PRIMARY KEY AUTOINCREMENT,coach_id INTEGER NOT NULL,student_id INTEGER,title TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT,status TEXT NOT NULL DEFAULT 'scheduled',notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,coach_id INTEGER NOT NULL,student_id INTEGER NOT NULL,sender_user_id INTEGER NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(sender_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,coach_id INTEGER NOT NULL,student_id INTEGER NOT NULL,amount_cents INTEGER NOT NULL,due_date TEXT NOT NULL,paid_at TEXT,status TEXT NOT NULL DEFAULT 'pending',description TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE progress_photos(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,file_path TEXT NOT NULL,caption TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE consents(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,document_type TEXT NOT NULL,document_version TEXT NOT NULL,accepted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_hash TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE app_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts(attempt_key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,first_attempt_at TEXT NOT NULL,last_attempt_at TEXT NOT NULL,blocked_until TEXT);
CREATE TABLE metrics(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,weight REAL NOT NULL,body_fat REAL NOT NULL,chest REAL NOT NULL DEFAULT 0,waist REAL NOT NULL DEFAULT 0,biceps REAL NOT NULL DEFAULT 0,thighs REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE workouts(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL,coach_id INTEGER NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TEXT,updated_at TEXT,archived_at TEXT,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE exercises(id INTEGER PRIMARY KEY AUTOINCREMENT,workout_id INTEGER NOT NULL,position INTEGER NOT NULL DEFAULT 0,library_exercise_id INTEGER,name TEXT NOT NULL,sets INTEGER NOT NULL,reps TEXT NOT NULL,load TEXT,rest_seconds INTEGER NOT NULL DEFAULT 60,notes TEXT,thumbnail TEXT,category TEXT,exercise_type TEXT,equipment TEXT,rpe INTEGER,tempo TEXT,instructions TEXT,FOREIGN KEY(workout_id) REFERENCES workouts(id) ON DELETE CASCADE);
CREATE INDEX idx_students_coach ON students(coach_id);
CREATE INDEX idx_metrics_student ON metrics(student_id,created_at);
CREATE INDEX idx_workouts_student ON workouts(student_id,status);
CREATE INDEX idx_password_reset_hash ON password_reset_tokens(token_hash);
CREATE TABLE exercise_library(id INTEGER PRIMARY KEY AUTOINCREMENT,coach_id INTEGER,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'GERAL',exercise_type TEXT NOT NULL DEFAULT 'ISOLADO',equipment TEXT NOT NULL DEFAULT 'LIVRE',media_url TEXT,media_type TEXT NOT NULL DEFAULT 'image',instructions TEXT,default_sets INTEGER NOT NULL DEFAULT 3,default_reps TEXT NOT NULL DEFAULT '10-12',default_rest INTEGER NOT NULL DEFAULT 60,default_rpe INTEGER NOT NULL DEFAULT 8,default_tempo TEXT NOT NULL DEFAULT '2-0-2-0',is_system INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coach_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE anamneses(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL UNIQUE,objective TEXT,conditions_json TEXT,injuries TEXT,experience TEXT,availability TEXT,sleep_hours REAL,stress_level INTEGER,notes TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE workout_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,workout_id INTEGER NOT NULL,student_id INTEGER NOT NULL,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,total_volume REAL NOT NULL DEFAULT 0,duration_seconds INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(workout_id) REFERENCES workouts(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE workout_set_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,exercise_id INTEGER,exercise_name TEXT NOT NULL,set_number INTEGER NOT NULL,reps INTEGER NOT NULL,load REAL NOT NULL DEFAULT 0,rpe REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(session_id) REFERENCES workout_sessions(id) ON DELETE CASCADE,FOREIGN KEY(exercise_id) REFERENCES exercises(id) ON DELETE SET NULL);
CREATE INDEX idx_library_coach ON exercise_library(coach_id,name);
CREATE INDEX idx_sessions_student ON workout_sessions(student_id,started_at);
